css:
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #fff;
    font-size: 10pt;
    color: #333;
}

.invoice-container {
    width: 100%;
    margin: 0 auto;
    padding: 20px;
}

/* Header Section */
.header-wrapper {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 10px;
    border-bottom: 1px solid #eee;
}

.logo-section {
    display: flex;
    align-items: center;
}

.logo-text {
    font-size: 24pt;
    font-weight: bold;
    color: #f7941d;
    margin-left: 200px;
    letter-spacing: 1px;
}

.logo-subtext {
    font-size: 14pt;
    color: #444;
    font-weight: normal;
}

.barcode-qr-section {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
}

.barcode-qr-section > div {
    margin-bottom: 5px;
}

.invoice-meta {
    display: flex;
    justify-content: space-between;
    padding: 10px 0;
    font-size: 9pt;
    border-bottom: 1px solid #ddd;
    flex-wrap: wrap;
}

.invoice-meta div {
    margin-right: 20px;
}

.meta-item div {
    margin-bottom: 3px;
}

.meta-label {
    font-weight: bold;
    color: #555;
    text-align: right;
}

.meta-value {
    font-weight: normal;
    color: #333;
}

/* Address Section */
.address-section {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0;
    padding: 20px 0;
}

.address-box {
    padding: 0;
}

.address-title {
    font-weight: bold;
    margin-bottom: 5px;
    color: #333;
    font-size: 10pt;
}

.address-box div {
    font-size: 9pt;
    line-height: 1.4;
    color: #555;
}

.address-box strong {
    color: #000;
    font-size: 10pt;
    font-weight: bold;
}

/* Items Table */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
}

.items-table thead {
    background: #4a86e8;
}

.items-table thead th {
    color: #ffffff !important;
}

.items-table th {
    padding: 10px 8px;
    text-align: left;
    font-weight: bold;
    font-size: 10pt;
    color: #ffffff;
}

.items-table td {
    padding: 8px;
    border-bottom: 1px solid #eee;
    font-size: 9pt;
    color: #333;
}

.items-table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

.items-table tr td:first-child,
.items-table tr th:first-child {
    text-align: center;
}

.items-table tr td:nth-child(3),
.items-table tr td:nth-child(4),
.items-table tr td:nth-child(5),
.items-table tr th:nth-child(3),
.items-table tr th:nth-child(4),
.items-table tr th:nth-child(5) {
    text-align: right;
}

/* Total Section */
.total-section {
    display: flex;
    justify-content: flex-end;
    margin-top: 15px;
}

.total-table {
    width: 300px;
    border-collapse: collapse;
    font-size: 10pt;
}

.total-table tr td {
    padding: 5px 15px;
    text-align: right;
    border-bottom: 1px solid #eee;
}

.total-table tr:last-child td {
    font-weight: bold;
    font-size: 11pt;
    color: #333;
    border-bottom: none;
}
